mapper.select:
select t_b_api_interface.id as api_interface_id, t_b_api_interface.plugin_id as api_interface_plugin_id, t_b_api_interface.code as api_interface_code, t_b_api_interface.name as api_interface_name, t_b_api_interface.description as api_interface_description, t_b_api_interface.path as api_interface_path, t_b_api_interface.method as api_interface_method, t_b_api_interface.api_version as api_interface_api_version, t_b_api_interface.price as api_interface_price, t_b_api_interface.billing_mode as api_interface_billing_mode, t_b_api_interface.need_key as api_interface_need_key, t_b_api_interface.rate_limit as api_interface_rate_limit, t_b_api_interface.enable as api_interface_enable, t_b_api_interface.access_mode as api_interface_access_mode, t_b_api_interface.create_time as api_interface_create_time, t_b_api_interface.update_time as api_interface_update_time, t_b_api_interface.version as api_interface_version from t_b_api_interface left join t_b_api_plugin tbap on tbap.plugin_id = t_b_api_interface.plugin_id and tbap.enable = 1
and t_b_api_interface.enable = 1
#{item}
#{item}
and (coalesce(t_b_api_interface.access_mode, tbap.default_access_mode, 'RESTRICTED') = 'DEFAULT'
#{item}
)
order by t_b_api_interface.name, t_b_api_interface.id
